  'assets/starter-packs/cars/steering-wheel.svg',
  'assets/starter-packs/cars/tractor.svg',
  'assets/starter-packs/cars/traffic-lights.svg',
  'assets/starter-packs/cars/ute.svg',
  'assets/starter-packs/cars/van.svg',
  'assets/starter-packs/cars/wheel.svg',
  'assets/starter-packs/garden-and-flowers/apple-tree.svg',
